// Guards scripts/build-user-guide.mjs's two exports against drift. Runs
// after build-user-guide.mjs in the prebuild chain (package.json), so
// src/data/user-guide-content.js is freshly generated by the time this
// imports it -- same ordering every other guide-content consumer relies on.
import fs from 'node:fs'
import { USER_GUIDE_CONTENT, USER_GUIDE_UNITS } from '../src/data/user-guide-content.js'
import { chapterFiles } from './lib/user-guide-order.mjs'
import { FOCUS_PLAYBOOK_UNIT_ORDER } from './lib/split-focus-playbook.mjs'

let failures = 0
const check = (ok, msg) => { if (!ok) { failures++; console.error(`  FAIL ${msg}`) } }

check(typeof USER_GUIDE_CONTENT === 'string' && USER_GUIDE_CONTENT.length > 200000,
  'USER_GUIDE_CONTENT is missing or suspiciously small -- api/claude.js (register reference) and api/coach.js (fallback) both need the whole guide here, unnarrowed')

const chapters = chapterFiles()
const expectedFocusUnits = FOCUS_PLAYBOOK_UNIT_ORDER.map(k => `focus-playbook:${k}`)
const expectedKeys = new Set([
  ...chapters.filter(f => f !== 'focus-playbook.md'),
  ...expectedFocusUnits,
])

const actualKeys = new Set(Object.keys(USER_GUIDE_UNITS))
check(actualKeys.size === expectedKeys.size,
  `USER_GUIDE_UNITS has ${actualKeys.size} keys, expected ${expectedKeys.size}`)
for (const key of expectedKeys) {
  check(actualKeys.has(key), `USER_GUIDE_UNITS is missing expected key "${key}"`)
}
for (const key of actualKeys) {
  check(expectedKeys.has(key), `USER_GUIDE_UNITS has unexpected key "${key}" -- not a chapter file and not a known focus-playbook unit`)
}

check(!actualKeys.has('focus-playbook.md'),
  'USER_GUIDE_UNITS carries focus-playbook.md whole -- it should only be reachable through its split units, or a step would get both the whole chapter and its own slice')
check(!actualKeys.has('index.md'),
  'USER_GUIDE_UNITS carries index.md -- the contents page is for a human browsing the guide, not Coach grounding for any step')

for (const key of actualKeys) {
  check(typeof USER_GUIDE_UNITS[key] === 'string' && USER_GUIDE_UNITS[key].trim().length > 0,
    `USER_GUIDE_UNITS["${key}"] is empty`)
}

// Whole-chapter units keep the "# filename\n\n" convention USER_GUIDE_CONTENT
// itself already uses, so a step-narrowed turn and the fallback read the
// same shape of content, not two different conventions.
for (const file of chapters.filter(f => f !== 'focus-playbook.md')) {
  check(USER_GUIDE_UNITS[file].startsWith(`# ${file}\n\n`),
    `USER_GUIDE_UNITS["${file}"] does not start with the "# ${file}" header USER_GUIDE_CONTENT's own chapters use`)
}

if (failures) {
  console.error(`test-build-user-guide: ${failures} check(s) failed`)
  process.exit(1)
} else {
  console.log(`test-build-user-guide: OK (USER_GUIDE_CONTENT intact, USER_GUIDE_UNITS carries exactly the expected ${expectedKeys.size} keys)`)
}
